//! TEXTAREA positive unsigned dimensions use actual attributes.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><textarea id=list cols=12 rows=3 name=q>Seed</textarea><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://textarea-dimensions.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn textarea_dimensions_canonical_accessors_and_native_initial_values(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('list');for(var key of ['cols','rows']){var a=Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype,key);if(!a||!a.enumerable||!a.configurable||a.get.length!==0||a.set.length!==1||a.get.name!=='get '+key||a.set.name!=='set '+key||Object.hasOwn(x,key))throw 'canonical dimension';}if(x.cols!==12||x.rows!==3||x.value!=='Seed'||x.defaultValue!=='Seed')throw 'native dimensions';");}
#[test]
fn textarea_dimensions_unsigned_conversion_fallback_and_actual_records(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('list'),attr=x.getAttributeNode('cols'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.cols=4294967303.9;x.rows=0;var records=watch.takeRecords();if(x.cols!==7||x.rows!==2||attr.value!=='7'||x.getAttribute('rows')!=='2'||x.getAttributeNode('cols')!==attr||records.length!==2||records[0].oldValue!=='12'||records[1].oldValue!=='3')throw 'unsigned fallback transaction';x.cols=-1;if(x.cols!==20||attr.value!=='20')throw 'high unsigned fallback';");}
#[test]
fn textarea_dimensions_inert_prefixes_namespace_and_copy(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=new Document(),x=owner.createElementNS('http://www.w3.org/1999/xhtml','p:textarea');if(x.cols!==20||x.rows!==2)throw 'missing defaults';x.setAttributeNS('urn:foreign','cols','99');x.setAttributeNS(null,'COLS','88');if(x.cols!==20)throw 'exact namespace';x.setAttributeNS(null,'cols','  +0017tail');x.setAttributeNS(null,'rows','4\ud800Z');var copy=x.cloneNode(false);if(x.cols!==17||x.rows!==4||copy.cols!==17||copy.rows!==4||copy.getAttributeNodeNS(null,'cols')===x.getAttributeNodeNS(null,'cols'))throw 'actual independent numeric prefix';copy.cols=0;if(copy.cols!==20||x.cols!==17)throw 'independent fallback';"#);}
#[test]
fn textarea_dimensions_once_number_conversion_and_abrupt_author_effect(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('list'),calls=0;x.cols={valueOf:function(){calls++;x.setAttribute('cols','author');return 6.9;},toString:function(){throw 'wrong hint';}};if(calls!==1||x.cols!==6||x.getAttribute('cols')!=='6')throw 'once numeric conversion';var marker={},caught;try{x.rows={valueOf:function(){x.setAttribute('rows','8tail');throw marker;}};}catch(e){caught=e;}if(caught!==marker||x.rows!==8||x.getAttribute('rows')!=='8tail')throw 'abrupt author effect';for(var bad of [Symbol('dimension'),BigInt(1)]){caught=false;try{x.cols=bad;}catch(e){caught=e instanceof TypeError;}if(!caught||x.cols!==6)throw 'numeric primitive refusal';}");}

#[test]
fn textarea_dimensions_getter_prefix_default_range_and_exact_namespace_matrix(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var x of [document.getElementById('list'),new Document().createElementNS('http://www.w3.org/1999/xhtml','t:textarea')]){for(var key of ['cols','rows']){var fallback=key==='cols'?20:2;x.removeAttribute(key);if(x[key]!==fallback)throw 'absent default';x.setAttributeNS('urn:foreign',key,'91');x.setAttributeNS(null,key==='cols'?'COLS':'ROWS','92');if(x[key]!==fallback)throw 'namespace case';for(var pair of [['',0],['  +0031tail',31],['2147483647.9',2147483647],['2147483648',0],['4294967295',0],['-1',0],['-0',0],['0x10',0],['3.9',3],['.9',0],['--1',0],['\u00a0 3',0],[' \t\n\f\r+7junk',7],['+0000030tail',30],['+',0],['1e10',1],['0000000000000000012',12],['9\ud800Z',9]]){x.setAttributeNS(null,key,pair[0]);var attr=x.getAttributeNodeNS(null,key);if(typeof x[key]!=='number'||x[key]!==(pair[1]||fallback)||attr.value!==pair[0]||x.getAttributeNodeNS(null,key)!==attr)throw 'HTML positive prefix without normalization';}}}"#);}
#[test]
fn textarea_dimensions_setter_webidl_unsigned_matrix_and_fallback(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var x of [document.getElementById('list'),new Document().createElementNS('http://www.w3.org/1999/xhtml','textarea')]){for(var key of ['cols','rows']){var fallback=key==='cols'?20:2;for(var pair of [['3.9',3],['0x10',16],[true,1],[false,0],[null,0],[undefined,0],[NaN,0],[Infinity,0],[-Infinity,0],[-0,0],[2147483647,2147483647],[2147483648,0],[4294967295,0],[4294967296,0],[-2147483649,2147483647],[-4294967295,1],[4294967297.9,1],[-3.9,0],['  +31  ',31]]){x[key]=pair[0];var expected=pair[1]||fallback;if(x[key]!==expected||x.getAttributeNS(null,key)!==String(expected))throw 'WebIDL unsigned positive fallback';}Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype,key).set.call(x);if(x[key]!==fallback||x.getAttributeNS(null,key)!==String(fallback))throw 'missing numeric argument fallback';}}"#);}
#[test]
fn textarea_dimensions_concrete_brand_before_conversion_author_override_and_saved_accessors(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('list'),C=HTMLTextAreaElement,P=C.prototype,calls=0;for(var key of ['cols','rows']){var a=Object.getOwnPropertyDescriptor(P,key);for(var bad of [{},Object.create(P),document.body,document.createElement('select'),document.createElement('input'),document.createElement('pre'),document.createElementNS('urn:foreign','textarea'),new Document().createElementNS('http://www.w3.org/1999/xhtml','TEXTAREA')]){var caught=false;try{a.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'dimension getter concrete brand';caught=false;try{a.set.call(bad,{valueOf:function(){calls++;return 1;}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'dimension setter brand before conversion';}Object.defineProperty(x,key,{value:'author',writable:true,configurable:true});a.set.call(x,3.9);if(x[key]!=='author'||a.get.call(x)!==3||x.getAttributeNS(null,key)!=='3')throw 'canonical authority';delete x[key];}delete window.HTMLTextAreaElement;var copy=x.cloneNode(false);if(!(copy instanceof C)||Object.getPrototypeOf(copy)!==P||copy.cols!==3||copy.rows!==3||document.getElementById('neighbor').value!=='seed')throw 'saved canonical dimension';"#);}
#[test]
fn textarea_dimensions_raw_attribute_aliases_observer_old_values_and_independent_copy(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var x of [document.getElementById('list'),new Document().createElementNS('http://www.w3.org/1999/xhtml','textarea')]){for(var key of ['cols','rows']){x.setAttributeNS(null,key,'12\ud800Z');var attr=x.getAttributeNodeNS(null,key);if(x[key]!==12||attr.value.charCodeAt(2)!==55296)throw 'raw dimension prefix';attr.nodeValue='7\udfffZ';var watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x[key]=4294967295;var records=watch.takeRecords(),fallback=key==='cols'?20:2;if(x[key]!==fallback||attr.value!==String(fallback)||x.getAttributeNodeNS(null,key)!==attr||records.length!==1||records[0].attributeName!==key||records[0].oldValue!=='7\udfffZ')throw 'normalization exact records';x.setAttributeNS(null,key,'8\ud800');watch.takeRecords();var copy=x.cloneNode(false);if(copy[key]!==8||copy.getAttributeNodeNS(null,key)===attr||copy.getAttributeNS(null,key).charCodeAt(1)!==55296)throw 'independent raw clone';copy[key]=4;if(x[key]!==8||copy[key]!==4||attr.value.charCodeAt(1)!==55296)throw 'independent dimension copy';}}"#);}
#[test]
fn textarea_dimensions_native_dirty_editor_defaults_flags_and_events_stay_stable(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('list'),events=0;x.oninput=function(){events++;};x.onchange=function(){events++;};x.value='Dirty';x.readOnly=true;x.required=true;var old=x.firstChild;");let node=*f.controls.keys().find(|node|d.attr(**node,"id")==Some("list")).unwrap();{let c=f.controls.get_mut(&node).unwrap();c.value.cursor=3;c.value.anchor=1;c.value.offset=1;}let snapshot=|f:&Forms|{let c=&f.controls[&node];(c.value.text(),c.value.cursor,c.value.anchor,c.value.offset,c.name.clone(),c.disabled,c.readonly,c.required,c.dirty_value)};let before=snapshot(&f);for code in ["x.cols=6;x.rows=5;","x.setAttribute('cols','8tail');x.setAttributeNS(null,'rows','7tail');","x.getAttributeNode('cols').value='9\\ud800';x.getAttributeNode('rows').textContent='4\\udfff';","x.removeAttribute('cols');x.removeAttribute('rows');"]{p.begin_job();run(&mut d,&mut f,&mut p,code);assert_eq!(snapshot(&f),before);run(&mut d,&mut f,&mut p,"if(x.value!=='Dirty'||x.defaultValue!=='Seed'||x.firstChild!==old||x.name!=='q'||!x.readOnly||!x.required||events)throw 'unchanged native editor defaults and events';");}}
#[test]
fn textarea_dimensions_saved_child_origin_precedes_number_conversion_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('list'),calls=0,frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLTextAreaElement.prototype,'cols');a.set.call(x,7);if(a.get.call(x)!==7)throw 'same origin dimension';");p.set_location(&crate::navigation::address("https://foreign-textarea-dimensions.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for code in ["a.get.call(x);","a.set.call(x,{valueOf:function(){calls++;return 1;}});"]{p.begin_job();let e=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.set_location(&crate::navigation::address("https://textarea-dimensions.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls||x.cols!==7)throw 'origin refusal before coercion';a.set.call(x,0);if(a.get.call(x)!==20||x.getAttribute('cols')!=='20')throw 'fresh dimension recovery';");}
#[test]
fn textarea_dimensions_reads_charge_payload_work_and_deadline_without_copy_or_retained_growth(){for key in ["cols","rows"]{for inert in [false,true]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','textarea');"}else{"var x=document.getElementById('list');"});run(&mut d,&mut f,&mut p,&format!("x.setAttribute('{key}','{}7');","0".repeat(128)));let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("genuine textarea")};let before=format!("{:?}",d.nodes);let retained=p.state.retained;let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.execution_deadline=Some(Instant::now()),2=>p.state.host_work=16,_=>{p.state.retained_limit=retained;p.state.copy_work=0;p.state.limits.host.string_bytes=0;}}let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.textarea_dimensions_get(object,key);if mode==3{assert!(matches!(result,Ok(Value::Number(7.0))));}else{assert!(result.is_err());}assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.retained,retained);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();assert!(matches!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.textarea_dimensions_get(object,key),Ok(Value::Number(7.0))));}}}}
#[test]
fn textarea_dimensions_writer_refusal_preserves_records_native_state_observers_and_recovers(){for key in ["cols","rows"]{for inert in [false,true]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','textarea');"}else{"var x=document.getElementById('list');x.removeAttribute('cols');x.removeAttribute('rows');"});run(&mut d,&mut f,&mut p,"var watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;let native=f.controls.iter().map(|(n,c)|(*n,c.value.text(),c.name.clone(),c.readonly,c.required,c.dirty_value)).collect::<Vec<_>>();p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.limits.host.string_bytes=0,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute(&format!("x.{key}=42;"),&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{key}/{inert}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.value.text(),c.name.clone(),c.readonly,c.required,c.dirty_value)).collect::<Vec<_>>(),native);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();let fallback=if key=="cols"{20}else{2};run(&mut d,&mut f,&mut p,&format!("if(x.{key}!=={fallback}||x.hasAttribute('{key}')||watch.takeRecords().length)throw 'atomic dimension refusal';x.{key}=42;var records=watch.takeRecords();if(x.{key}!==42||x.getAttribute('{key}')!=='42'||records.length!==1||records[0].oldValue!==null)throw 'fresh dimension writer recovery';"));}}}}
